class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
        j=dict()
        for k in range(len(nums)):
            j[nums[k]]=k
        for i in range(len(nums)):
            if target-nums[i] in j and j[target-nums[i]]!=i:
                return [j[target-nums[i]],i]

